export type LessonPackMode = 'quick' | 'source' | 'debate'

export type ActivityPackMode = 'warmup' | 'source-lab' | 'roleplay' | 'debate' | 'writing' | 'compare' | 'extension'

export type ActivityPack = {
  id: string
  title: string
  mode: ActivityPackMode
  durationMinutes: number
  audience: string
  prompt: string
  materials: string[]
  steps: string[]
  deliverable: string
  successCriteria: string[]
  linkedSourceTitles: string[]
  linkedSceneBeatTitles: string[]
}

export type LessonPack = {
  inquiryQuestion: string
  quickStart: string[]
  classroomFlow: Record<LessonPackMode, {
    title: string
    steps: string[]
  }>
  checkQuestions: {
    question: string
    answer: string
    teacherNote: string
  }[]
  misconceptions: {
    misconception: string
    correction: string
  }[]
  discussionRoles: {
    role: string
    task: string
  }[]
  exitTickets: string[]
}

export type DecisionOption = {
  id: string
  label: string
  stance: string
  description: string
  immediate: string
  longTerm: string
  reflection: string
}

export type Scenario = {
  id: string
  title: string
  era: string
  year: number
  location: string
  region: string
  coordinates: [number, number]
  identity: string
  role: string
  age: number
  theme: string
  accent: string
  summary: string
  atmosphere: string
  sceneBeats: SceneBeat[]
  dailyLife: DailyLifeSection[]
  timeline: TimelineEvent[]
  decision: {
    prompt: string
    context: string
    options: DecisionOption[]
  }
  realHistory: string
  interpretationNote: string
  lessonPack: LessonPack
  activityPacks: ActivityPack[]
  missions: Mission[]
  socialActors: SocialActor[]
  socialEncounters: SocialEncounter[]
  materialObjects: MaterialObject[]
  keyTerms: KeyTerm[]
  compareAngles: CompareAngle[]
  sourceEvidenceUse: string
  sources: HistoricalSource[]
}

