    realHistory:
      '基尔瓦基西瓦尼是中世纪斯瓦希里海岸最重要的城邦之一，尤其在 13-14 世纪与黄金贸易、印度洋季风网络、伊斯兰城市文化和石造建筑密切相关。伊本·白图泰约 1331 年到访并留下赞美性记述；《基尔瓦编年史》保存王朝和地方记忆；遗址、陶瓷、钱币、建筑和考古研究显示基尔瓦与更广的印度洋世界相连。',
